WITH flattened AS (SELECT id, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, attr_value) SELECT id, latency_ms, attr_key, NTILE(4) OVER (PARTITION BY attr_key ORDER BY status_code, id, attr_key) AS status_code_bucket, NTILE(3) OVER (ORDER BY status_code, id, attr_key) AS status_code_bucket_2, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY log_ts DESC, id, attr_key) AS row_seq, CORR(latency_ms, status_code) OVER w_ordered AS corr_latency_ms_status_code FROM flattened WINDOW w_ordered AS (PARTITION BY attr_key);
